                <div class="bar-label left">Cool proxy baseline</div><div class="bar-label right">Warming present day</div>
                <div class="baseline-marker ipcc"><div class="tag">~1.2 °C</div></div>
                <div class="baseline-marker true"><div class="tag">~1.7 °C</div></div>
                <div class="delta-badge">hidden +0.5 °C</div>
