        .catch(function(error) { console.error('PNG download failed', error); });
    }
    var ChartManager = {
      charts: new Map(),
      safeInit: function(canvasId, config) {
        if (typeof Chart === 'undefined') {
          console.error('Chart.js library not loaded - check CDN inclusion');
          return null;
        }
        try {
          if (this.charts.has(canvasId)) {
            this.charts.get(canvasId).destroy();
            this.charts.delete(canvasId);
          }
          var ctx = document.getElementById(canvasId);
          if (!ctx) {
            console.error('Canvas element not found: ' + canvasId);
            return null;
          }
          if (ctx.chart) {
            ctx.chart.destroy();
            delete ctx.chart;
          }
          ctx.setAttribute('role', 'img');
          if (!ctx.getAttribute('aria-label')) ctx.setAttribute('aria-label', 'Chart visualization');
          var chart = new Chart(ctx, config);
          ctx.chart = chart;
          this.charts.set(canvasId, chart);
          return chart;
        } catch (error) {
          console.error('Chart initialization failed for ' + canvasId, error);
          return null;
        }
      }
    };
    var climatePlugin = {
      id: 'climatePlugin',
      beforeDatasetsDraw: function(chart) {
        var ctx = chart.ctx;
        var x = chart.scales.x;
        var y = chart.scales.y;
        if (!x || !y) return;
        function xPos(year) { return x.getPixelForValue(year); }
        function yPos(temp) { return y.getPixelForValue(temp); }
        ctx.save();
        var area = chart.chartArea;
        var grad = ctx.createLinearGradient(area.left, 0, area.right, 0);
        grad.addColorStop(0, 'rgba(56, 157, 214, 0.18)');
        grad.addColorStop(0.45, 'rgba(130, 205, 231, 0.10)');
        grad.addColorStop(0.75, 'rgba(255, 185, 76, 0.11)');
        grad.addColorStop(1, 'rgba(241, 82, 58, 0.16)');
        ctx.fillStyle = grad;
        ctx.fillRect(area.left, area.top, area.right - area.left, area.bottom - area.top);
        var thresholdY = yPos(1.5);
        ctx.setLineDash([18, 12]);
        ctx.lineWidth = 4;
        ctx.strokeStyle = 'rgba(255, 216, 100, 0.92)';
        ctx.beginPath();
        ctx.moveTo(area.left, thresholdY);
        ctx.lineTo(area.right, thresholdY);
        ctx.stroke();
        ctx.setLineDash([]);
        ctx.fillStyle = 'rgba(255, 216, 100, 0.98)';
        ctx.font = '800 28px Inter';
        ctx.fillText('Paris Agreement threshold: 1.5 °C', area.left + 28, thresholdY - 18);
        var ipccX0 = xPos(1850), ipccX1 = xPos(1900);
        ctx.fillStyle = 'rgba(139, 202, 255, 0.13)';
        ctx.fillRect(ipccX0, area.top, ipccX1 - ipccX0, area.bottom - area.top);
        ctx.fillStyle = 'rgba(179, 218, 255, 0.95)';
        ctx.font = '750 24px Inter';
        ctx.save();
        ctx.translate((ipccX0 + ipccX1) / 2, area.bottom - 24);
        ctx.rotate(-Math.PI / 2);
        ctx.textAlign = 'left';
        ctx.fillText('1850–1900 IPCC baseline ≈ +0.5 °C', 0, 0);
        ctx.restore();
        var baseX0 = xPos(1700), baseX1 = xPos(1790);
        ctx.fillStyle = 'rgba(47, 156, 255, 0.12)';
        ctx.fillRect(baseX0, area.top, baseX1 - baseX0, area.bottom - area.top);
        ctx.fillStyle = 'rgba(160, 220, 255, 0.95)';
        ctx.font = '750 24px Inter';
        ctx.fillText('true pre-industrial baseline', baseX0 + 18, area.top + 38);
        var crossX = xPos(2018), crossY = yPos(1.5);
        ctx.strokeStyle = 'rgba(255,255,255,0.90)';
        ctx.lineWidth = 4;
        ctx.beginPath();
        ctx.arc(crossX, crossY, 18, 0, Math.PI * 2);
        ctx.stroke();
        ctx.fillStyle = '#ff594a';
        ctx.beginPath();
        ctx.arc(crossX, crossY, 10, 0, Math.PI * 2);
        ctx.fill();
        ctx.fillStyle = 'rgba(255,255,255,0.97)';
        ctx.font = '850 30px Inter';
        ctx.fillText('1.5 °C crossed', crossX - 18, crossY - 56);
        ctx.font = '650 22px Inter';
        ctx.fillStyle = 'rgba(235,246,255,0.92)';
        ctx.fillText('early 2020s', crossX + 48, crossY - 28);
        ctx.restore();
      }
    };
    Chart.register(climatePlugin);
    function createTemperatureTimeline() {
      if (typeof Chart === 'undefined') { console.error('Chart.js not loaded'); return; }
      var years = [1700,1720,1740,1760,1780,1790,1810,1830,1850,1870,1890,1900,1920,1940,1960,1980,2000,2010,2020,2024];
      var proxy = [0.00,-0.02,0.03,-0.01,0.04,0.02,0.13,0.28,0.43,0.50,0.55,0.58,0.68,0.82,0.86,1.02,1.25,1.39,1.63,1.70];
      var instrumental = years.map(function(year, i) { return year >= 1850 ? proxy[i] - 0.50 : null; });
      ChartManager.safeInit('temperatureTimeline', {
        type: 'line',
        data: {
          labels: years,
          datasets: [
            {
              label: 'Sclerosponge reconstruction vs 1700–1790 baseline',
              data: proxy,
              borderColor: '#ff8a45',
              backgroundColor: 'rgba(255, 138, 69, 0.22)',
              borderWidth: 8,
              pointRadius: 6,
              pointHoverRadius: 9,
              pointBackgroundColor: '#fff3d6',
              pointBorderColor: '#ff7b3d',
              pointBorderWidth: 3,
              tension: 0.34,
              fill: true
            },
            {
              label: 'Conventional instrumental framing (1850–1900 baseline)',
              data: instrumental,
              borderColor: '#79c8ff',
              backgroundColor: 'rgba(121, 200, 255, 0.08)',
              borderWidth: 5,
              pointRadius: 0,
              pointHoverRadius: 5,
              borderDash: [14, 10],
              tension: 0.34,
              fill: false
            }
          ]
        },
        options: {
          responsive: true,
          maintainAspectRatio: false,
          interaction: { intersect: false, mode: 'index' },
          plugins: {
            tooltip: { enabled: true },
            legend: {
              display: true,
              position: 'top',
              align: 'start',
              labels: { color: '#d7ebf8', font: { family: 'Inter', size: 25, weight: 700 }, boxWidth: 38, boxHeight: 16, padding: 22 }
            }
          },
          scales: {
            x: {
              type: 'linear', min: 1700, max: 2025,
              grid: { color: 'rgba(255,255,255,0.08)', lineWidth: 2 },
              border: { color: 'rgba(255,255,255,0.22)' },
              ticks: { color: '#c9ddea', font: { family: 'Inter', size: 25, weight: 700 }, stepSize: 50, callback: function(value) { return value; } },
              title: { display: true, text: 'Year CE', color: '#d8edf9', font: { family: 'Inter', size: 30, weight: 800 }, padding: { top: 16 } }
            },
            y: {
              min: -0.2, max: 1.9,
              grid: { color: 'rgba(255,255,255,0.08)', lineWidth: 2 },
              border: { color: 'rgba(255,255,255,0.22)' },
              ticks: { color: '#c9ddea', font: { family: 'Inter', size: 25, weight: 700 }, stepSize: 0.25, callback: function(value) { return value.toFixed(2).replace('.00','') + ' °C'; } },
              title: { display: true, text: 'Temperature anomaly relative to 1700–1790 baseline', color: '#d8edf9', font: { family: 'Inter', size: 30, weight: 800 }, padding: { bottom: 18 } }
            }
          }
        }
      });
    }
    createTemperatureTimeline();
    window.onThemeChange = createTemperatureTimeline;
  </script>
