const { chromium } = require('playwright');
const path = require('path');
(async () => {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage({ viewport: { width: 2384, height: 3370 }, deviceScaleFactor: 1 });
  const errors = [];
  page.on('console', msg => {
    if (msg.type() === 'error') errors.push(msg.text());
  });
  page.on('pageerror', err => errors.push(err.message));
  await page.goto('file://' + path.resolve('/app/output_poster.html'), { waitUntil: 'networkidle' });
  await page.evaluate(() => document.body.classList.add('hidden-for-png'));
  await page.waitForTimeout(750);
  const poster = page.locator('#poster');
  await poster.screenshot({ path: '/app/output/final_poster.png', animations: 'disabled' });
  await browser.close();
  if (errors.length) {
    console.error(errors.join('\n'));
    process.exit(2);
  }
})();
